:"test","path":"packages/operator-core/lib/code-intelligence/packer-facade.test.ts","anchor":"it('secret-scanning can never be disabled","proves":"No-security-check is excluded from every constructed repomix argument vector."}]},"sources":[{"path":"packages/operator-core/lib/code-intelligence/packer-facade.test.ts","startLine":147,"text":"    }
