 * pin, an empty include set and a genuinely-empty selection are five distinct
 * states, and each returns something that says which.
 */
export async function packerFacade(
  op: PackerOp,
  args: PackerArgs,
  effects: PackerEffects = DEFAULT_PACKER_EFFECTS,
): Promise<PackerResult> {
  const started = Date.now();
  const engine: PackerEngine = op === 'diff' ? 'code2prompt' : 'repomix';
  const format: PackFormat = args.format ?? (op === 'diff' ? 'markdown' : 'xml');
  const query = `${op}:${args.include.join(',')}${args.baseRef ? ` vs ${args.baseRef}` : ''}`;

  if (!(await getFlag(FLAGS.CODE_INTEL_PACKERS, 'system').catch(() => false))) {
    return refusal(engine, query, `packing is disabled (${FLAGS.CODE_INTEL_PACKERS} is off)`, started);
  }
  if (args.include.length === 0) {
    return refusal(
      engine,
      query,
      'an explicit, non-empty include set is required (P-016): an unscoped pack of this monorepo is ' +
        'evidence nobody chose, and it is indistinguishable from a correctly-scoped one until read.',
      started,
    );
  }

  const id = await packerIdentity(engine, effects.exec);
  if (!id.ok) return refusal(engine, query, id.reason, started);

  let argv: string[];
  try {
    argv = engine === 'repomix' ? buildRepomixArgs(args) : buildCode2PromptArgs(args);
  } catch (err) {
    return refusal(engine, query, err instanceof Error ? err.message : String(err), started);
  }

  let body: string;
  try {
    const { stdout } = await effects.exec(id.identity.bin, argv, {
      cwd: args.rootPath,

 * better than defaulting, because a silently-whole-repo pack looks exactly like
 * a correctly-scoped one until someone reads it.
 */
export function buildRepomixArgs(args: PackerArgs): string[] {
  if (args.include.length === 0) {
    throw new Error(
      'repomix requires an explicit, non-empty include set (P-016). Packing the whole tree by ' +
        'default produces evidence nobody scoped.',
    );
  }
  assertNotFlagShaped(args.include, 'include');
  assertNotFlagShaped(args.ignore ?? [], 'ignore');
  const ignore = [...(args.ignore ?? []), ...SECRET_DENY_GLOBS];
  // `--flag=value` throughout: an attached value is unambiguous to the parser,
  // so no emitted token can be re-read as an option.
  const argv = [
    '--stdout',
    '--quiet',
    `--style=${args.format === 'markdown' ? 'markdown' : 'xml'}`,
    `--include=${args.include.join(',')}`,
    `--ignore=${ignore.join(',')}`,
  ];
  if (args.compress) argv.push('--compress');
  assertNoForbidden(argv, REPOMIX_FORBIDDEN_FLAGS, 'repomix');
  return argv;
}

/**
 * Build code2prompt's argv. PURE.
 *
 * Always `-O -` (stdout): there is no caller-supplied output path anywhere in
 * this builder, so the engine cannot write into the shared tree behind the lock
 * arbitration.
 */
export function buildCode2PromptArgs(args: PackerArgs): string[] {
  if (args.include.length === 0) {
    throw new Error('code2prompt requires an explicit, non-empty include set (P-016).');
  }
  assertNotFlagShaped(args.include, 'include');
  assertNotFlagShaped(args.ignore ?? [], 'ignore');

  }
});

it('secret-scanning can never be disabled — --no-security-check is absent always', () => {
  for (const args of ARG_MATRIX) {
    expect(buildRepomixArgs(args)).not.toContain('--no-security-check');
  }
});

it('code2prompt always writes to STDOUT and the target cannot be rebound', () => {
  for (const args of ARG_MATRIX) {
    const argv = buildCode2PromptArgs(args);
    expect(argv, 'output target must be pinned to stdout').toContain('--output-file=-');
    // exactly one output target, so none can be smuggled in behind it
    expect(argv.filter((t) => t.startsWith('--output-file'))).toHaveLength(1);
    expect(argv.filter((t) => t === '-O')).toHaveLength(0);
  }
});

it('REFUSES every smuggling attempt outright, rather than sanitising it', () => {
  for (const args of SMUGGLING_MATRIX) {
    expect(() => buildRepomixArgs(args), JSON.stringify(args)).toThrow(/begins with '-'/);
    expect(() => buildCode2PromptArgs(args), JSON.stringify(args)).toThrow(/begins with '-'/);
  }
});

it('REFUSES a flag-shaped baseRef', () => {
  expect(() => buildCode2PromptArgs({ ...BASE, baseRef: '--clipboard' })).toThrow(/begins with '-'/);
});

it('emits ATTACHED values, so no emitted token can be re-read as an option', () => {
  // The second, independent defence: even if a pattern slipped past
  // validation, `--include=<value>` is unambiguous to every argv parser,
  // whereas `--include <value>` is not.
  for (const args of ARG_MATRIX) {
    const argv = buildRepomixArgs(args);
    expect(argv.some((t) => t.startsWith('--include='))).toBe(true);
    expect(argv).not.toContain('--include');
    expect(argv).not.toContain('--ignore');
  }

 * workspace-scoped Queen, which legitimately recalls across the workspace's
 * hives) or resolves to no hive (a plain standalone harness). Pure — the registry
 * IO + flag gate live at the call site. */
export function narrowHarnessSlugsToSessionHive(
  entries: readonly RegistryEntryLite[],
  harnessSlugs: readonly string[],
  sessionHarness: string | null | undefined,
): string[] {
  if (!sessionHarness || sessionHarness === '*') return [...harnessSlugs];
  const scopeHive = potSlugsForHarnesses(entries, [sessionHarness])[0];
  if (!scopeHive) return [...harnessSlugs]; // session not in a hive → no narrowing
  const bySlug = new Map(entries.map((e) => [e.slug, e]));
  return harnessSlugs.filter((slug) => {
    const e = bySlug.get(slug);
    if (!e) return false; // unknown slug → drop from a confined fan-out
    const hive = e.harness_kind === 'hive' ? e.slug : e.hive_slug;
    return hive === scopeHive;
  });
}

