  });

  it('returns a fresh array (no aliasing of the input) on the pass-through path', () => {
    const out = narrowHarnessSlugsToSessionHive(entries, allSlugs, '*');
    expect(out).not.toBe(allSlugs);
    expect(out).toEqual(allSlugs);
  });
});

