 */
export function buildCode2PromptArgs(args: PackerArgs): string[] {
  if (args.include.length === 0) {
    throw new Error('code2prompt requires an explicit, non-empty include set (P-016).');
  }
  assertNotFlagShaped(args.include, 'include');
